<?php
declare(strict_types=1);
function game_allowed_views():array{return['MINIGAME_MEMORY','MINIGAME_MATH','MINIGAME_PATTERN','MINIGAME_SPEED','MINIGAME_VISUALIZATION','MINIGAME_ORIENTATION','MINIGAME_STROOP','MINIGAME_MULTITASK','MINIGAME_FACTFINDING','MINIGAME_5WHYS','MINIGAME_SWOT','MINIGAME_CYNEFIN','MINIGAME_ROLEPLAY'];}
function handle_game_route(string $method,string $path):bool{if($path!=='/game'&&strpos($path,'/game/')!==0)return false;if($path==='/game/nodes'){if($method!=='GET')method_not_allowed(['GET']);success_response(['order'=>journey_node_order(),'nodes'=>array_values(journey_nodes())]);return true;}if($path==='/game/complete'){if($method!=='POST')method_not_allowed(['POST']);game_complete();return true;}if($path==='/game/memory-progress'){if($method!=='POST')method_not_allowed(['POST']);game_memory_progress();return true;}if($path==='/game/bigfive'){if($method!=='POST')method_not_allowed(['POST']);game_bigfive();return true;}error_response('NOT_FOUND','مسیر بازی پیدا نشد.',404);return true;}
function game_complete():void{$pdo=Database::pdo();$a=require_auth();$d=read_json_body();reject_unknown_keys($d,['gameView','nodeId','rawScore','payload'],'ثبت نتیجه بازی');$game=require_allowed(require_string($d,'gameView',80),game_allowed_views(),'gameView');$node=null;if(array_key_exists('nodeId',$d)&&$d['nodeId']!==null&&$d['nodeId']!=='')$node=clean_string($d['nodeId'],80);$raw=require_number($d,'rawScore',0,1000000);$payload=(isset($d['payload'])&&is_array($d['payload']))?$d['payload']:[];$pdo->beginTransaction();try{$s=load_profile_state($pdo,(int)$a['user']['id'],true);$xp_multipliers=['MINIGAME_MATH'=>0.03,'MINIGAME_MEMORY'=>1.5,'MINIGAME_PATTERN'=>1.5,'MINIGAME_SPEED'=>1.5,'MINIGAME_VISUALIZATION'=>1.5,'MINIGAME_ORIENTATION'=>1.5,'MINIGAME_STROOP'=>1.5,'MINIGAME_MULTITASK'=>1.5,'MINIGAME_NBACK'=>30,'MINIGAME_FACTFINDING'=>1.5,'MINIGAME_5WHYS'=>1.5,'MINIGAME_SWOT'=>1.5,'MINIGAME_CYNEFIN'=>1.5,'MINIGAME_ROLEPLAY'=>1.5];$mult=$xp_multipliers[$game]??1.5;$xp=(int)floor($raw*$mult);$prog=apply_assessment_points($s,$xp);$s['total_scenarios']=(int)$s['total_scenarios']+1;apply_activity_streak($s);$nodeProg=complete_journey_node($s,$node);apply_skill_update($s['skills'],$game,$raw);if(apply_cognitive_raw_update($s['cognitive_raw'],$game,$raw,$payload))$s['cognitive_t']=calculate_indices($s['cognitive_raw']);$pdo->prepare('INSERT INTO game_results (user_id,game_view,node_id,raw_score,xp_earned,payload,created_at) VALUES (?,?,?,?,?,?,NOW())')->execute([(int)$a['user']['id'],$game,$node,$raw,$xp,$payload?json_for_db($payload):null]);save_profile_state($pdo,(int)$a['user']['id'],$s);$pdo->commit();$u=fetch_user_by_id($pdo,(int)$a['user']['id']);success_response(['profile'=>build_user_profile($u,$s),'xpEarned'=>$xp,'progression'=>$prog,'nodeProgress'=>$nodeProg]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
function game_memory_progress():void{$pdo=Database::pdo();$a=require_auth();$d=read_json_body();reject_unknown_keys($d,['subType','score','rawScore'],'پیشرفت حافظه');$sub=require_allowed(require_string($d,'subType',20),['corsi','pairs','nback'],'subType');$score=require_number($d,'score',0,1000000);$raw=isset($d['rawScore'])?number_value($d['rawScore'],0,1000000):$score;$pdo->beginTransaction();try{$s=load_profile_state($pdo,(int)$a['user']['id'],true);$s['memory_sub_scores'][$sub]=max((int)$s['memory_sub_scores'][$sub],(int)round($score));$mem=(int)round(((int)$s['memory_sub_scores']['corsi']+(int)$s['memory_sub_scores']['pairs']+(int)$s['memory_sub_scores']['nback'])/3);set_skill_max($s['skills'],'memory',$mem);if($sub==='corsi')set_raw_max($s['cognitive_raw'],'A9a_Corsi',(float)$raw);elseif($sub==='pairs')set_raw_max($s['cognitive_raw'],'A9b_Paired',(float)$raw);else set_raw_max($s['cognitive_raw'],'A9c_NBack',(float)$raw);$s['cognitive_t']=calculate_indices($s['cognitive_raw']);save_profile_state($pdo,(int)$a['user']['id'],$s);$pdo->commit();$u=fetch_user_by_id($pdo,(int)$a['user']['id']);success_response(['profile'=>build_user_profile($u,$s),'memorySubScores'=>$s['memory_sub_scores']]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
function game_bigfive():void{$pdo=Database::pdo();$a=require_auth();$d=read_json_body();reject_unknown_keys($d,['scores'],'ثبت Big Five');if(!isset($d['scores'])||!is_array($d['scores']))error_response('VALIDATION_ERROR','فیلد scores برای Big Five الزامی است.',422);$scores=validate_big_five_scores($d['scores']);$pdo->beginTransaction();try{$s=load_profile_state($pdo,(int)$a['user']['id'],true);$s['big_five']=$scores;$prog=apply_assessment_points($s,250);$s['total_scenarios']=(int)$s['total_scenarios']+1;apply_activity_streak($s);$pdo->prepare('INSERT INTO game_results (user_id,game_view,node_id,raw_score,xp_earned,payload,created_at) VALUES (?,"MINIGAME_BIGFIVE",NULL,250,250,?,NOW())')->execute([(int)$a['user']['id'],json_for_db(['scores'=>$scores])]);save_profile_state($pdo,(int)$a['user']['id'],$s);$pdo->commit();$u=fetch_user_by_id($pdo,(int)$a['user']['id']);success_response(['profile'=>build_user_profile($u,$s),'xpEarned'=>250,'progression'=>$prog]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();throw$e;}}
